const staticData = $getWorkflowStaticData('global');
const statusCode = $json.statusCode || $response?.statusCode || 0;
const now = Date.now();
const threshold = 2;
const cooldownMs = 6 * 60 * 60 * 1000;
const isFailure = !statusCode || statusCode >= 500;
if (!staticData.failCount) staticData.failCount = 0;
if (!staticData.lastAlertAt) staticData.lastAlertAt = 0;
if (!staticData.alertOpen) staticData.alertOpen = false;
if (isFailure) {
  staticData.failCount += 1;
} else {
  const recovered = staticData.alertOpen === true;
  staticData.failCount = 0;
  staticData.alertOpen = false;
  if (recovered) {
    return [{ json: { action: 'recovered', send: true, text: '✅ Vespera recovered\n\nhttps://vespera-nabit.vercel.app is responding normally again.' } }];
  }
  return [{ json: { action: 'healthy', send: false, statusCode } }];
}
if (staticData.failCount < threshold) {
  return [{ json: { action: 'waiting_for_second_failure', send: false, failCount: staticData.failCount, statusCode } }];
}
if ((now - staticData.lastAlertAt) < cooldownMs) {
  return [{ json: { action: 'cooldown', send: false, failCount: staticData.failCount, statusCode } }];
}
staticData.lastAlertAt = now;
staticData.alertOpen = true;
return [{ json: { action: 'alert', send: true, text: `🚨 Vespera health check failing\n\nURL: https://vespera-nabit.vercel.app\nStatus: ${statusCode || 'timeout/network'}\nFailures in a row: ${staticData.failCount}` } }];
